"""A* vs Dijkstra on a 2D grid: same optimal path length, far fewer expansions."""

import heapq

MOVES = ((-1, 0), (1, 0), (0, -1), (0, 1))


def _search(grid, start, goal, use_heuristic):
    """Shared core. h = Manhattan if use_heuristic else always 0 (Dijkstra)."""
    rows, cols = len(grid), len(grid[0])

    def passable(r, c):
        return 0 <= r < rows and 0 <= c < cols and grid[r][c] != '#'

    sr, sc = start
    gr, gc = goal
    if not (passable(sr, sc) and passable(gr, gc)):
        return None, 0
    if start == goal:
        return [start], 0

    def h(cell):
        return abs(cell[0] - gr) + abs(cell[1] - gc) if use_heuristic else 0

    # heap entries: (f, -g, cell) -> ties on f prefer larger g (closer to goal)
    g_best = {start: 0}
    parent = {}
    open_heap = [(h(start), 0, start)]
    closed = set()
    expanded = 0

    while open_heap:
        f, neg_g, cur = heapq.heappop(open_heap)
        if cur in closed:
            continue
        closed.add(cur)
        expanded += 1
        if cur == goal:
            path = [cur]
            while cur in parent:
                cur = parent[cur]
                path.append(cur)
            return path[::-1], expanded
        cr, cc = cur
        for dr, dc in MOVES:
            nxt = (cr + dr, cc + dc)
            if not passable(*nxt) or nxt in closed:
                continue
            ng = g_best[cur] + 1
            if ng < g_best.get(nxt, float('inf')):
                g_best[nxt] = ng
                parent[nxt] = cur
                heapq.heappush(open_heap, (ng + h(nxt), -ng, nxt))
    return None, expanded


def astar(grid, start, goal):
    """A* with Manhattan heuristic. Returns (path | None, nodes_expanded)."""
    return _search(grid, start, goal, use_heuristic=True)


def dijkstra(grid, start, goal):
    """Uniform-cost search (A* with h=0). Returns (path | None, nodes_expanded)."""
    return _search(grid, start, goal, use_heuristic=False)


def render(grid, path):
    """Return a copy of the grid with the path drawn as '*'."""
    out = [list(row) for row in grid]
    for r, c in path or []:
        if out[r][c] == '.':
            out[r][c] = '*'
    return [''.join(row) for row in out]


if __name__ == '__main__':
    import random
    rng = random.Random(42)
    rows = cols = 25
    grid = [
        ''.join('#' if rng.random() < 0.25 else '.' for _ in range(cols))
        for _ in range(rows)
    ]
    grid[0] = 'S' + grid[0][1:]          # mark start visually below
    grid[0] = '.' + grid[0][1:]
    start, goal = (0, 0), (rows - 1, cols - 1)
    grid[goal[0]] = grid[goal[0]][:-1] + 'G'

    path, n_exp = astar(grid, start, goal)
    print(f"A*: path length {len(path)}, expanded {n_exp} nodes\n")
    shown = render(grid, path)
    shown[start[0]] = 'S' + shown[start[0]][1:]
    shown[goal[0]] = shown[goal[0]][:-1] + 'G'
    print('\n'.join(shown))

